  "claims": [
    {
      "claim": "The query is furosemide; the closest supplied measured context is bumetanide, which shares the sulfamoylbenzoic acid diuretic core and has measured human absolute oral bioavailability of 0.66–0.86 (66–86%) across multiple studies, with L2 records describing 80–100% and near-complete oral bioavailability.",
      "card_ids": ["C08","C12","C14","C15","C24","C29"]
    },
    {
      "claim": "All other supplied measured oral-bioavailability contexts are above the 20% threshold: PAS 50–60%, probenecid ~100%, diclofenac ~50%, bromfenac 67%, safinamide 95%, amlodipine 58%, rigosertib 35%, PF-05241328 38%, and telmisartan 42%.",
      "card_ids": ["C20","C02","C01","C10","C03","C19","C06","C04","C07"]
    },
    {
      "claim": "L6 hepatic-clearance records for azosemide, the closest structural analog (tetrazole replaces the carboxyl and thienylmethyl replaces furfuryl), show low rat hepatic microsomal intrinsic clearance (2.70 and 4.51 ×10^-3 ml/min) and substantial unchanged parent in S9; bumetanide shows no CYP2E1-mediated clearance. This is mechanistic evidence against a large hepatic first-pass loss, though not a direct F measurement.",
      "card_ids": ["C73","C74","C79","C81"]
    },
    {
      "claim": "No supplied record provides affirmative threshold-relevant evidence for F<20%; the unfavorable physicochemical prior (low logD, high TPSA, full ionization) is not endpoint proof and is outweighed by measured F in structurally related acids.",
      "card_ids": ["C08","C20","C02","C24","C29"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C73","C74","C79","C81"]
    }
  ],
  "evidence_gaps": [
    "No direct furosemide-specific absolute bioavailability or matched oral/IV AUC record is supplied; prediction relies on structural analogy to bumetanide and other sulfamoyl/aminobenzoic acid contexts.",
    "No query-specific human hepatic clearance or metabolic-stability measurement is supplied; L6 azosemide data are from rat hepatic microsomes/S9 and bumetanide CYP2E1 data are indirect.",
    "Fasted-state condition is matched for several contexts, but PAS, probenecid, bumetanide, and PF-05241328 records do not specify prandial state; dose and formulation also differ.",
    "Low permeability or efflux findings for sulfasalazine, 5-ASA, and other L5 reference molecules are not transferable to furosemide without query-specific data."
  ],
  "decision_summary": "The query is furosemide. L1/L2 records for bumetanide and other sulfamoyl/aminobenzoic acid contexts show measured human absolute oral bioavailability well above 20% (e.g., bumetanide 66–86%, PAS 50–60%, probenecid ~100%, diclofenac ~50%, bromfenac 67%, safinamide 95%). L6 hepatic-clearance records for the close analog azosemide show low rat hepatic intrinsic clearance and substantial unchanged parent, and bumetanide shows no CYP2E1-mediated clearance, providing mechanistic support against a large first-pass loss. No supplied record affirmatively supports F<20%. Prediction remains high with high confidence."
}

